      setHistory(data[11]||[]);setReceipts(data[12]||[]);setProspects(data[0]);setQuotes(data[1].sort((a,b)=>b.quote_no-a.quote_no));setVisits(data[2].sort((a,b)=>new Date(b.happened_at)-new Date(a.happened_at)));setOrders(data[3].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)));setPayments(data[4]);setQa(data[5]);setShipments(data[6]);setInvoices(data[7]);setGoals(data[8]);if(data[9]?.length)setCatalog(data[9]);if(data[10]?.[0]){setBilling(data[10][0]);setBillingEdit(data[10][0].bank_iban);setBankConfirmed(!!data[10][0].bank_account_confirmed)}
