  async function login(kind){setAuthBusy(true);setError('');try{if(!loginEmail.includes('@'))throw new Error('Anna sähköpostiosoite.');if(kind==='password'){const {error}=await client.auth.signInWithPassword({email:loginEmail.trim(),password});if(error)throw error;}else{const {error}=await client.auth.signInWithOtp({email:loginEmail.trim(),options:{shouldCreateUser:false,emailRedirectTo:window.location.origin}});if(error)throw error;announce('Kirjautumislinkki lähetetty, jos osoite on sallittu.')} }catch(e){setError(e.message)}finally{setAuthBusy(false)}}
